L["Units and objects in the world."] = "Einheiten und Objekte in der Spielwelt."
L["Unmute Tab"] = "Tab wieder aktivieren"
L["Unpin"] = "Fixierung aufheben"
L["Until you pick a palette here, the bars follow the unit frames' palette."] = "Bis du hier eine Farbpalette auswählst, übernehmen die Balken die Farbpalette der Einheitenfenster."
L["Unusable"] = "Nicht verwendbar"
