L["Use Quality of Life"] = "Komfortfunktionen verwenden"
L["Use the Game Language"] = "Spielsprache verwenden"
L["use the last button"] = "Die letzte Schaltfläche verwenden"
L["use the lit button"] = "Die hervorgehobene Schaltfläche verwenden"
L["Use the mouse for this list."] = "Verwende für diese Liste die Maus."
L["Uses your class's own spells, so it means range for you."] = "Verwendet die eigenen Zauber deiner Klasse und zeigt daher deine persönliche Reichweite an."
L["Value"] = "Wert"
L["Value [Max]"] = "Wert [Maximum]"
L["Value | Health Lost"] = "Wert | Verlorene Lebenspunkte"
L["Value | Percent"] = "Wert | Prozent"
L["Value and Percent"] = "Wert und Prozent"
L["Values on Mouseover"] = "Werte beim Darüberfahren anzeigen"
L["Vehicle Exit"] = "Fahrzeug verlassen"
L["Vendor"] = "Händler"
L["Vendors show 20 items a page instead of 10, in four columns."] = "Händler zeigen 20 statt 10 Gegenstände pro Seite in vier Spalten an."
L["Version, credits and what's new on FlareUI."] = "Version, Mitwirkende und Neuigkeiten zu FlareUI."
