L["Worn Trinkets"] = "Angelegte Schmuckstücke"
L["Wowhead Link"] = "Wowhead-Link"
L["Wowhead link (Ctrl+C to copy)"] = "Wowhead-Link (mit Ctrl+C kopieren)"
L["Wowhead shows the ID in the spell's web address."] = "Wowhead zeigt die ID in der Webadresse des Zaubers an."
L["Wrap"] = "Zeilenumbruch"
L["WTB %s x20, paying well"] = "Kaufe %s x20, zahle gut"
L["XP"] = "EP"
